FUNCTION_BLOCK FB_S02
VAR_INPUT
    FwdBtn : BOOL;
    RevBtn : BOOL;
    MaintKey : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    MotorFwd : BOOL := FALSE;
    MotorRev : BOOL := FALSE;
    RunLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    StartupScans : UINT := UINT#0;
    LastDirection : INT := 0;       (* 0 = 无历史方向，1 = 正转，-1 = 反转 *)
    RequestedDirection : INT := 0;
    OffTicks : UINT := UINT#0;      (* 饱和于10：10个20 ms间隔 *)
    BlinkTicks : UINT := UINT#0;    (* 0..49：1 Hz，50%占空比 *)
    WasRunning : BOOL := FALSE;
    StartupInhibit : BOOL := TRUE;
END_VAR

(*
    待审语义：
    1. 条款1的立即启动要求与C10的G[0,1]启动禁止存在边界冲突；
       本实现按明确的C10抑制前两次调用。
    2. 两按钮同时有效且输出均断开时，条款1可能同时要求两方向启动，
       与K1冲突。该输入组合采用安全停机，不声明其为已确认的仲裁需求。
    3. 普通态RunLamp行为未明示；本实现指示任一方向实际运行。
    未声称经过编译或逐周期功能验证。
*)

(* 保存上一扫描输出，再统一断开；后续只允许设置一个方向。 *)
WasRunning := MotorFwd OR MotorRev;
MotorFwd := FALSE;
MotorRev := FALSE;
Status := WORD#16#0000;

StartupInhibit := StartupScans < UINT#2;
IF StartupInhibit THEN
    StartupScans := StartupScans + UINT#1;
END_IF;

RequestedDirection := 0;
IF FwdBtn AND NOT RevBtn THEN
    RequestedDirection := 1;
ELSIF RevBtn AND NOT FwdBtn THEN
    RequestedDirection := -1;
END_IF;

(*
    上一扫描仍运行时，本扫描为首次断开，累计时间为0。
    连续断开的后续扫描每次累计20 ms，避免少等待一个扫描。
    即使按钮释放或进入检修，也保留最后运行方向。
*)
IF WasRunning THEN
    OffTicks := UINT#0;
ELSIF OffTicks < UINT#10 THEN
    OffTicks := OffTicks + UINT#1;
END_IF;

(* 检修闪灯独立于急停状态码：钥匙有效时始终显示检修闪烁。 *)
IF MaintKey THEN
    RunLamp := BlinkTicks < UINT#25;
    IF BlinkTicks >= UINT#49 THEN
        BlinkTicks := UINT#0;
    ELSE
        BlinkTicks := BlinkTicks + UINT#1;
    END_IF;
ELSE
    BlinkTicks := UINT#0;
    RunLamp := FALSE;
END_IF;

(* 安全优先级：急停 > 检修 > 启动抑制 > 方向控制。 *)
IF NOT EStop_NC THEN
    OffTicks := UINT#0;
    Status := WORD#16#8202;

ELSIF MaintKey THEN
    Status := WORD#16#8201;

ELSIF StartupInhibit THEN
    Status := WORD#16#0000;

ELSIF RequestedDirection <> 0 THEN
    IF (LastDirection <> 0)
       AND (RequestedDirection <> LastDirection)
       AND (OffTicks < UINT#10) THEN
        Status := WORD#16#8203;
    ELSE
        IF RequestedDirection = 1 THEN
            MotorFwd := TRUE;
        ELSE
            MotorRev := TRUE;
        END_IF;
        LastDirection := RequestedDirection;
        OffTicks := UINT#0;
    END_IF;
END_IF;

IF NOT MaintKey THEN
    RunLamp := MotorFwd OR MotorRev;
END_IF;

END_FUNCTION_BLOCK
